async function main() {
  try {
    console.log('Iniciando carga simulada...');
    await prisma.historialVerificacion.deleteMany();
    await prisma.instrumentoEquipo.deleteMany();
    
    // 1. Crear equipos
    for (const e of EQUIPOS) {
      await prisma.instrumentoEquipo.create({ data: e });
    }
    
    // 2. Crear historiales
    for (const h of HISTORIAL) {
      await prisma.historialVerificacion.create({ data: h });
    }

    // 3. ACTUALIZACIÓN CRÍTICA: Ajustar el estado de cada equipo según su última verificación
    console.log('Actualizando estados finales...');
    const allEquipos = await prisma.instrumentoEquipo.findMany();
    for (const eq of allEquipos) {
      if (eq.Estado === 'OBSOLETO') continue; // Respetar obsoletos manuales

      const ultima = await prisma.historialVerificacion.findFirst({
        where: { FK_ID_Equipo: eq.ID_Equipo },
        orderBy: { Fecha_Ejecucion: 'desc' }
      });

      if (ultima && ultima.Resultado_Status === 'NO_APTO') {
        await prisma.instrumentoEquipo.update({
          where: { ID_Equipo: eq.ID_Equipo },
          data: { Estado: 'NO_APTO' }
        });
      }
    }
    
    console.log('Carga finalizada con exito.');
  } catch (e) {
    console.error(e);
  } finally {
    await prisma.$disconnect();
  }
}
main();
